<?/*******************************************************************************************	entradamercancia:Realiza la entrada de mercancia de un punto de venta por otros conceptos 	que no son el ingreso contra pedidos.			$frm: array con los datos de entrada de mercancia	Retorna:				Void*******************************************************************************************/function entradamercancia( $frm ){	Global $Nombre_Usuario, $ID_Usuario, $IDPuntoVenta;		//Insertar los Items en la tabla de detalles		$Items = $frm['ITEM'];		for($i = 1; $i <= $Items; $i++)	{				$iddetalle = get_maxID("DetalleMovimiento WHERE IDMovimiento = '$frm[IDMovimiento]'","IDDetalleMovimiento");		$IDCodificacion = "IDCodificacion".$i;		$Cantidad = "Cantidad".$i;		$IDPuntoVentaReferencia = get_field( "CodificacionEspecifica","IDPuntoVentaReferencia","IDCodificacionEspecifica", $frm[$IDCodificacion]);		$IDTalla = get_field( "CodificacionEspecifica","IDTalla","IDCodificacionEspecifica", $frm[$IDCodificacion]);				$str_insert_detalle  = "INSERT INTO DetalleMovimiento ( IDDetalleMovimiento,IDMovimiento,IDPuntoVentaReferencia,IDPuntoVenta,IDTalla,Cantidad,UsuarioTrCr,FechaTrCr ) ";		$str_insert_detalle .= "VALUES ( '$iddetalle','$frm[IDMovimiento]','$IDPuntoVentaReferencia','$frm[IDPuntoVenta]','$IDTalla','$frm[$Cantidad]','$frm[UsuarioTrCr]','$frm[FechaTrCr]' )";		//echo $str_insert_detalle .= "<br>";				db_query( $str_insert_detalle );				//insertar el log		insertlog($ID_Usuario,"DetalleMovimiento",$iddetalle,"Insertar",$str_insert_detalle);		}//end for($i = 1; $i < $Items; $i++)		//Realizar el Movimiento correspondiente en la tabla de Codificacion especifica	for($i = 1; $i <= $Items; $i++)	{				$IDCodificacion = "IDCodificacion".$i;		$Cantidad = "Cantidad".$i;		$existencias = get_field( "CodificacionEspecifica","Existencias","IDCodificacionEspecifica", $frm[$IDCodificacion]);				$existencias = $existencias + $frm[$Cantidad];				$str_actualiza_inventario  = "UPDATE CodificacionEspecifica SET Existencias = '$existencias' WHERE IDCodificacionEspecifica = '$frm[$IDCodificacion]'";		//echo $str_actualiza_inventario .= "<br>";				db_query( $str_actualiza_inventario );				//insertar el log		insertlog($ID_Usuario,"CodificacionEspecifica",$frm[$IDCodificacion],"Insertar",$str_actualiza_inventario);			}//end for($i = 1; $i < $Items; $i++)	}//end function entradamercancia( $frm )?>
